mapper.select:
select  dataTable.warning_order_id as warningOrderId,dataTable.warning_source,dataTable.warning_type_id,dataTable.alarm_time,dataTable.tenant_id,dataTable.tenant_name,dataTable.longitude,
dataTable.latitude,dataTable.alarm_body,dataTable.remark,dataTable.description,dataTable.address,dataTable.process_id,dataTable.process_name,dataTable.emergency_level,dataTable.order_status,
dataTable.flow_node_time,dataTable.find_name,dataTable.find_mobile,dataTable.file_img_url_src as imgUrl,dataTable.file_img_url_src,dataTable.file_img_url_icon fileImgUrlIcon,dataTable.video_url videoUrl,
dataTable.create_time as createDate,dataTable.time_limit,dataTable.grid_name,
dataTable.modifier_date as checkTime,dataTable.duplicate_order_id,dataTable.group_id,
dataTable.province_code as provinceId,
dataTable.province_name as provinceName,
dataTable.city_code as cityId,
dataTable.city_name as cityName,
dataTable.county_code as countyId,
dataTable.county_name as countyName,
IFNULL(dataTable.grid_id,'') as gridId,
dataTable.device_name AS deviceName,
dataTable.channel_name AS channelName,
dataTable.device_code as deviceCode,
dataTable.channel_code as channelCode,
dataTable.enable_acceptance_mode as enableAcceptanceMode,
dataTable.judge_result as judgeResult,
dataTable.importance_level AS importanceLevel,

    ST_Distance_Sphere(
    ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')),
    ST_GeomFromText(CONCAT('POINT(',dataTable.longitude,' ',dataTable.latitude,')'))
    ) as distance,

dataTable.flow_id,
dataTable.link_id,
case when (dataTable.process_id like CONCAT(CONCAT('%', #{param.userId, jdbcType=VARCHAR}), '%')) then 1 else 0 end  ifEdit
from ${param.tableName} as dataTable
where dataTable.delete_flag = '0'
AND dataTable.longitude !='' AND dataTable.longitude IS NOT NULL AND dataTable.latitude !='' AND dataTable.latitude IS NOT NULL
${param.dataScope}


    and dataTable.warning_source in

        #{item}



    and (dataTable.order_status in

        #{item}


        or dataTable.enable_acceptance_mode = #{param.enableAcceptanceMode}


        and dataTable.enable_acceptance_mode != '1'

    )









    AND (dataTable.warning_order_id like concat('%',#{param.keyword,jdbcType=VARCHAR},'%') OR dataTable.alarm_body like concat('%',#{param.keyword,jdbcType=VARCHAR},'%'))


    and dataTable.alarm_time >= #{param.alarmTimeStart}


    and dataTable.alarm_time <= #{param.alarmTimeEnd}


    AND dataTable.tenant_id = #{param.tenantId}



    AND dataTable.industry_code = #{param.industryCode}


    AND dataTable.province_code = #{param.provinceId}


    and dataTable.grid_id = #{param.gridId}


    AND dataTable.city_code = #{param.cityId}


    AND dataTable.county_code = #{param.countyId}


    and ST_Distance_Sphere(
    ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')),
    ST_GeomFromText(CONCAT('POINT(',dataTable.longitude,' ',dataTable.latitude,')'))
    ) <= #{param.radius}

order by dataTable.alarm_time desc

    limit #{param.limitCount}

SELECT a.alarm_body AS alarmBody, a.warning_order_id AS warningOrderId, a.warning_type_id AS warningTypeId, a.warning_source AS warningSource, IF(a.alarm_time IS NULL,'',DATE_FORMAT(a.alarm_time,'%Y-%m-%d %H:%i:%s')) as alarmTime, a.province_code AS provinceId, a.city_code AS cityId, a.county_code AS countyId, a.province_name as provinceName, a.city_name as cityName, a.county_name as countyName, a.address, a.longitude, a.latitude, a.emergency_level AS emergencyLevel, a.importance_level AS importanceLevel, a.tenant_id AS tenantId, a.device_code AS deviceCode, a.channel_code AS channelCode, a.channel_name as channelName, a.device_name as deviceName, a.alarm_code AS alarmCode, a.tenant_name AS tenantName, a.order_status AS orderStatus, a.find_name AS findName, a.find_mobile AS findMobile, CONCAT(SUBSTRING(a.find_mobile,1,3),'****',SUBSTRING(a.find_mobile,8)) AS encryptionMobilePhone, a.description, a.remark, a.voice, IFNULL(a.video_url,'') as videoUrl, IFNULL(a.file_img_url_src,'') as fileImgUrlSrc, IFNULL(a.file_img_url_icon,'') as fileImgUrlIcon, IFNULL(a.grid_id,'') as gridId, IFNULL(a.grid_name,'') as gridName, a.judge_result as judgeResult, if(a.flow_template is null,1,locate('2',a.flow_template)) as ifSend, a.duplicate_order_id duplicateOrderId, a.flow_id as flowId, a.link_id as linkId, a.alarm_param as alarmParam, a.alarm_param_value as alarmParamValue, a.extra_field as extraField, a.app_ver_code as appVerCode, a.hori_azimuth_angle as horiAzimuthAngle, IFNULL(a.confidence_level,'') as confidenceLevel, IFNULL(a.front_alarm_pic_url,'') as frontAlarmPicUrl, IFNULL(a.front_alarm_vedio_url,'') as frontAlarmVedioUrl, IFNULL(a.comp_confidence_level,'') as compConfidenceLevel, a.confidence_level_min confidenceLevelMin, a.notice_resource noticeResource, a.msg_type msgType, a.task_id AS taskId, a.preset_id as presetId, a.device_pitch as devicePitch, a.device_horizontal as deviceHorizontal, a.real_link_type realLinkType FROM ${param.tableName} a WHERE a.duplicate_order_id = #{param.duplicateOrderId,jdbcType=VARCHAR}
and a.alarm_time >= #{param.alarmTimeStart}
and a.alarm_time <= #{param.alarmTimeEnd}
AND (a.warning_order_id like concat('%',#{param.keyword,jdbcType=VARCHAR},'%') OR a.alarm_body like concat('%',#{param.keyword,jdbcType=VARCHAR},'%'))
${param.dataScope}
order by a.alarm_time
desc
asc
order by a.importance_level
desc,a.alarm_time desc
asc,a.alarm_time desc
order by a.alarm_time desc
